import { describe, expect, it } from 'vitest';
import { loadConfig } from '../src/config';
import { RateLimiter } from '../src/lib/limiter';
import { setup } from './helpers';

describe('POST /webhooks rate limiting', () => {
  it('answers 429 with a Retry-After header when a tenant exceeds the configured limit', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 2, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(202);

    const limited = await postWebhook('tenant-a', { type: 'c' });
    expect(limited.status).toBe(429);
    const retryAfter = limited.headers.get('Retry-After');
    expect(retryAfter).not.toBeNull();
    expect(Number(retryAfter)).toBeGreaterThan(0);
    expect(await limited.json()).toMatchObject({ error: 'rate limit exceeded' });
  });

  it('does not affect other tenants', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 1, rateLimitWindowMs: 60000 });
    expect((await postWebhook('tenant-a', { type: 'a' })).status).toBe(202);
    expect((await postWebhook('tenant-a', { type: 'b' })).status).toBe(429);
    expect((await postWebhook('tenant-b', { type: 'b' })).status).toBe(202);
  });

  it('reads the limit and window from config', async () => {
    const { postWebhook } = setup({ rateLimitMaxRequests: 3, rateLimitWindowMs: 60000 });
    for (let i = 0; i < 3; i += 1) {
      expect((await postWebhook('tenant-a', { type: `t${i}` })).status).toBe(202);
    }
    expect((await postWebhook('tenant-a', { type: 'over' })).status).toBe(429);

    const roomier = setup({ rateLimitMaxRequests: 4, rateLimitWindowMs: 60000 });
    for (let i = 0; i < 3; i += 1) {
      expect((await roomier.postWebhook('tenant-a', { type: `t${i}` })).status).toBe(202);
    }
    expect((await roomier.postWebhook('tenant-a', { type: 'fourth' })).status).toBe(202);
  });

  it('allows requests again once the window slides past', async () => {
    const limiter = new RateLimiter();
    expect(limiter.check('tenant-a', 1, 1000, 0).allowed).toBe(true);
    expect(limiter.check('tenant-a', 1, 1000, 500).allowed).toBe(false);
    expect(limiter.check('tenant-a', 1, 1000, 1001).allowed).toBe(true);
  });

  it('loads rate limit defaults and env values through loadConfig', () => {
    expect(loadConfig({})).toMatchObject({ rateLimitMaxRequests: 100, rateLimitWindowMs: 60000 });
    expect(loadConfig({ RATE_LIMIT_MAX_REQUESTS: '2', RATE_LIMIT_WINDOW_MS: '5000' })).toMatchObject({
      rateLimitMaxRequests: 2,
      rateLimitWindowMs: 5000,
    });
  });
});

